    "presence.tour.doors.capSiteUs": "ביקשתם מאיתנו אתר, אז בנינו לכם אחד מההגדרות שלכם: השירותים, המחירים והשעות. תקראו, תלחצו פרסום, והוא באוויר בכתובת משלכם.",
    "presence.tour.doors.capSiteNone": "בחרתם לא לקחת אתר דרכנו. זו בחירה לגיטימית, אפשר לשנות דעה בכל רגע, וכל מה שלמטה עובד גם בלי אתר.",
    "presence.tour.doors.capOwn": "כבר יש לכם אתר משלכם? תשאירו אותו. חברו את הג׳ימייל או האאוטלוק, וכל פנייה שהטופס שלכם שולח במייל נשמרת כאן כאיש קשר, באותו מסלול כמו שלנו.",
    "presence.tour.doors.capContact": "קישור טופס יצירת הקשר הוא דף שממנו אפשר לשלוח לכם הודעה. הוא מיועד לאתר בלי טופס, או למי שאין לו אתר בכלל. הוא פעיל מהרגע הראשון.",
